135: static struct extent_node *__init_extent_tree(struct f2fs_sb_info *sbi,
136: 				struct extent_tree *et, struct extent_info *ei)
137: {
138: 	struct rb_node **p = &et->root.rb_node;
139: 	struct extent_node *en;
